# H03 v002
from itertools import product as _prod
def _mul(p, q):
    r = [0] * (len(p) + len(q) - 1)
    for i, x in enumerate(p):
        for j, y in enumerate(q): r[i + j] += x * y
    return r
def _fila(n):
    f = [1]
    for _ in range(n): f = [1] + [f[i] + f[i + 1] for i in range(len(f) - 1)] + [1]
    return f
def _pw(n):
    p = [1]
    for _ in range(n): p = _mul(p, [1, 1])
    return p
