from fractions import Fraction as _F14
def _mul14(P, Q):  # producto de polinomios de Laurent {exponente: coeficiente}
    R = {}
    for e1, c1 in P.items():
        for e2, c2 in Q.items(): R[e1 + e2] = R.get(e1 + e2, 0) + c1 * c2
    return {e: c for e, c in R.items() if c != 0}
def _pot14(P, n):  # potencia por multiplicación directa (sin usar el binomio de Newton)
    R = {0: 1}
    for _ in range(n): R = _mul14(R, P)
    return R
def _coef14(P, n, m): return _pot14(P, n).get(m, 0)
